//! Writing generated files. A generator that only adds files leaves a deleted
//! shape's old file behind, so crucible empties its output directory first.
//! To make that safe it only empties a directory it marked as its own.

use std::fs;
use std::io;
use std::path::Path;

const MARKER: &str = ".crucible";
const MARKER_TEXT: &str =
    "Generated by crucible. This directory is emptied and rewritten on every run.\n";

pub(crate) fn write<'a>(
    out: &Path,
    files: impl IntoIterator<Item = (&'a str, &'a str)>,
) -> io::Result<()> {
    if out.exists() {
        let owned = out.join(MARKER).is_file();
        let empty = fs::read_dir(out)?.next().is_none();
        if !owned && !empty {
            return Err(io::Error::other(format!(
                "{} holds files crucible did not write (no {MARKER} marker); refusing to empty it",
                out.display()
            )));
        }
        for entry in fs::read_dir(out)? {
            let path = entry?.path();
            // Installed dependencies and build output are the consumer's, and
            // costly to recreate.
            let name = path
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or_default();
            if matches!(name, "node_modules" | "dist" | "target") {
                continue;
            }
            if path.is_dir() {
                fs::remove_dir_all(&path)?;
            } else {
                fs::remove_file(&path)?;
            }
        }
    }
    fs::create_dir_all(out)?;
    fs::write(out.join(MARKER), MARKER_TEXT)?;
    for (relative, contents) in files {
        let path = out.join(relative);
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::write(path, contents)?;
    }
    Ok(())
}
